-- A GUEST ENTERS, AND A SLIP IS PRINTED (J39/J40 PR 3). Additive only: two columns on Event and five on
-- PlayerPass (A044's table), all with constant defaults or nullable, and one PARTIAL unique index. Nothing is
-- dropped, renamed or backfilled. One migration for all of PR 3 (design §2.1), so only one of its pieces pays
-- for a schema change. Generated by `prisma migrate diff --from-schema-datamodel <origin/main's schema>
-- --to-schema-datamodel <this branch> --script` (read-only, no database touched); the partial index is
-- hand-written, as registrationToken's is (35_open_registration), because Prisma cannot express it.

-- AlterTable
ALTER TABLE "Event" ADD COLUMN     "guestEntryOpen" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "registrationCode" TEXT NOT NULL DEFAULT '';

-- AlterTable
ALTER TABLE "PlayerPass" ADD COLUMN     "entryNonceAt" TIMESTAMP(3),
ADD COLUMN     "entryNonceHash" TEXT NOT NULL DEFAULT '',
ADD COLUMN     "entryNote" TEXT NOT NULL DEFAULT '',
ADD COLUMN     "slipPrintedAt" TIMESTAMP(3),
ADD COLUMN     "slipPrintedVersion" INTEGER;

-- CreateIndex: unique only where a code has been made; every event that never needed one keeps "".
CREATE UNIQUE INDEX "Event_registrationCode_key" ON "Event"("registrationCode") WHERE "registrationCode" <> '';
